using System; using System.Data.OleDb; using System.IO; using System.Reflection; using UCSPyayStudentRegistration.Helpers;
namespace UCSPyayStudentRegistration.Database {
 public static class DatabaseInitializer {
  public static void EnsureDatabase(){Directory.CreateDirectory(DbConnection.DataDirectory);if(!File.Exists(DbConnection.DatabasePath)){CreateMdb();CreateTables();Seed();}EnsureStudentSoftDeleteColumn();EnsureReferenceData();}
  static void EnsureStudentSoftDeleteColumn(){using(var c=DbConnection.Open()){try{using(var x=new OleDbCommand("SELECT TOP 1 IsActive FROM Students",c))x.ExecuteScalar();}catch(OleDbException){Exec(c,"ALTER TABLE Students ADD COLUMN IsActive YESNO");Exec(c,"UPDATE Students SET IsActive=True");}}}
  static void EnsureReferenceData(){using(var c=DbConnection.Open()){bool admission=false;using(var x=new OleDbCommand("SELECT SeatNumber FROM AdmissionList",c))using(var r=x.ExecuteReader())while(r.Read())if(string.Equals(Convert.ToString(r[0]).Trim(),"PYAY-2026-001",StringComparison.OrdinalIgnoreCase)){admission=true;break;}if(!admission)using(var x=DbConnection.Command("INSERT INTO AdmissionList (SeatNumber,StudentName,University,AcademicYear,IsEligible) VALUES (?,?,?,?,?)",c,"PYAY-2026-001","Aung Aung","University of Computer Studies, Pyay","2026-2027",true))x.ExecuteNonQuery();int sid=0;using(var x=new OleDbCommand("SELECT StudentId,UniversityRollNo FROM Students",c))using(var r=x.ExecuteReader())while(r.Read())if(string.Equals(Convert.ToString(r[1]).Trim(),"PaKaPaTa-002198",StringComparison.OrdinalIgnoreCase)){sid=Convert.ToInt32(r[0]);break;}if(sid==0){using(var x=DbConnection.Command("INSERT INTO Students (StudentName,Gender,DateOfBirth,NRC,Phone,Email,UniversityRollNo,Major,[Year],AcademicYear,CreatedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?)",c,"Maung Maung","Male",new DateTime(2005,1,10),"7/PaMaNa(N)111111","09123456789","maung@example.com","PaKaPaTa-002198","Computer Science",2,"2026-2027",DateTime.Now))x.ExecuteNonQuery();using(var x=new OleDbCommand("SELECT @@IDENTITY",c))sid=Convert.ToInt32(x.ExecuteScalar());}int results;using(var x=DbConnection.Command("SELECT COUNT(*) FROM SemesterResults WHERE StudentId=?",c,sid))results=Convert.ToInt32(x.ExecuteScalar());if(results==0)using(var x=DbConnection.Command("INSERT INTO SemesterResults (StudentId,AcademicYear,Semester,ResultText,IsPassed,ResultDate) VALUES (?,?,?,?,?,?)",c,sid,"2025-2026",2,"Passed",true,new DateTime(2026,6,1)))x.ExecuteNonQuery();}}
  static void EnsureDemoAdmin(){using(var c=DbConnection.Open()){bool found=false;using(var x=new OleDbCommand("SELECT Username FROM Users",c))using(var r=x.ExecuteReader()){while(r.Read())if(string.Equals(Convert.ToString(r[0]).Trim(),"admin",StringComparison.OrdinalIgnoreCase)){found=true;break;}}if(!found){string salt=PasswordHelper.NewSalt(),hash=PasswordHelper.Hash("Admin@123",salt);using(var x=DbConnection.Command("INSERT INTO Users (Username,PasswordHash,PasswordSalt,Role,IsActive,CreatedAt) VALUES (?,?,?,?,?,?)",c,"admin",hash,salt,"Admin",true,DateTime.Now))x.ExecuteNonQuery();}}}
  static void CreateMdb(){var t=Type.GetTypeFromProgID("ADOX.Catalog");if(t==null)throw new InvalidOperationException("Microsoft Jet/Access Database Engine is not installed.");object cat=Activator.CreateInstance(t);try{t.InvokeMember("Create",BindingFlags.InvokeMethod,null,cat,new object[]{DbConnection.ConnectionString});}finally{System.Runtime.InteropServices.Marshal.FinalReleaseComObject(cat);}}
  static void Exec(OleDbConnection c,string sql){using(var cmd=new OleDbCommand(sql,c))cmd.ExecuteNonQuery();}
  static void CreateTables(){using(var c=DbConnection.Open()){
   string[] sql={
    "CREATE TABLE Users (UserId AUTOINCREMENT PRIMARY KEY, Username TEXT(50) NOT NULL, PasswordHash TEXT(255) NOT NULL, PasswordSalt TEXT(255) NOT NULL, Role TEXT(30) NOT NULL, IsActive YESNO NOT NULL, CreatedAt DATETIME NOT NULL)",
    "CREATE UNIQUE INDEX UX_Users_Username ON Users(Username)",
    "CREATE TABLE Students (StudentId AUTOINCREMENT PRIMARY KEY, StudentName TEXT(100) NOT NULL, EnglishName TEXT(100), Gender TEXT(10), DateOfBirth DATETIME, NRC TEXT(30), Phone TEXT(30), Email TEXT(100), ProfilePhotoPath TEXT(255), UniversityRollNo TEXT(40), Major TEXT(80), [Year] INTEGER, AcademicYear TEXT(20), [Address] MEMO, CreatedAt DATETIME)",
    "CREATE UNIQUE INDEX UX_Students_Roll ON Students(UniversityRollNo)",
    "CREATE TABLE Parents (ParentId AUTOINCREMENT PRIMARY KEY, StudentId LONG NOT NULL, FatherName TEXT(100), FatherNrc TEXT(30), FatherPhone TEXT(30), FatherOccupation TEXT(80), FatherAddress MEMO, MotherName TEXT(100), MotherNrc TEXT(30), MotherPhone TEXT(30), MotherOccupation TEXT(80), MotherAddress MEMO)",
    "CREATE TABLE Guardians (GuardianId AUTOINCREMENT PRIMARY KEY, StudentId LONG NOT NULL, GuardianName TEXT(100), NRC TEXT(30), Relationship TEXT(50), Occupation TEXT(80), Phone TEXT(30), [Address] MEMO)",
    "CREATE TABLE AdmissionList (AdmissionId AUTOINCREMENT PRIMARY KEY, SeatNumber TEXT(40) NOT NULL, StudentName TEXT(100), University TEXT(150), AcademicYear TEXT(20), IsEligible YESNO)",
    "CREATE UNIQUE INDEX UX_Admission_Seat ON AdmissionList(SeatNumber)",
    "CREATE TABLE SemesterResults (ResultId AUTOINCREMENT PRIMARY KEY, StudentId LONG NOT NULL, AcademicYear TEXT(20), Semester INTEGER, ResultText TEXT(30), IsPassed YESNO, ResultDate DATETIME)",
    "CREATE TABLE Applications (ApplicationId AUTOINCREMENT PRIMARY KEY, ApplicationNo TEXT(30), StudentId LONG NOT NULL, [Year] INTEGER, AcademicYear TEXT(20), Status TEXT(30), CorrectionVersion INTEGER, CorrectionReason MEMO, RegistrationFee CURRENCY, SeatOrRoll TEXT(50), SubmittedDate DATETIME, LastUpdated DATETIME, ApprovedDate DATETIME, RejectedDate DATETIME, RejectReason MEMO)",
    "CREATE UNIQUE INDEX UX_Applications_No ON Applications(ApplicationNo)",
    "CREATE TABLE ApplicationHistory (HistoryId AUTOINCREMENT PRIMARY KEY, ApplicationId LONG NOT NULL, [Version] INTEGER, Status TEXT(30), [Action] TEXT(80), Reason MEMO, ChangedItems MEMO, PerformedBy TEXT(80), CreatedAt DATETIME)",
    "CREATE TABLE Documents (DocumentId AUTOINCREMENT PRIMARY KEY, ApplicationId LONG NOT NULL, DocumentType TEXT(80), FileName TEXT(255), FilePath TEXT(255), FileType TEXT(20), FileSize LONG, VerificationStatus TEXT(30), AdminNote MEMO, UploadedAt DATETIME, VerifiedAt DATETIME)",
    "CREATE TABLE Payments (PaymentId AUTOINCREMENT PRIMARY KEY, ApplicationId LONG NOT NULL, RequiredAmount CURRENCY, PaidAmount CURRENCY, PaymentMethod TEXT(40), TransactionId TEXT(100), PaymentDate DATETIME, ReceiptFilePath TEXT(255), PaymentStatus TEXT(30), VerifiedBy TEXT(80), VerifiedAt DATETIME)",
    "CREATE INDEX IX_Payments_Transaction ON Payments(TransactionId)",
    "CREATE TABLE Refunds (RefundId AUTOINCREMENT PRIMARY KEY, ApplicationId LONG NOT NULL, PaymentId LONG NOT NULL, RefundEligibility TEXT(30), RefundAmount CURRENCY, RefundReason MEMO, RefundStatus TEXT(30), RefundDate DATETIME, RefundReference TEXT(100), ProcessedBy TEXT(80))",
    "CREATE TABLE StudentCards (CardId AUTOINCREMENT PRIMARY KEY, StudentId LONG NOT NULL, ApplicationId LONG NOT NULL, RegistrationCode TEXT(60) NOT NULL, IssuedAt DATETIME)",
    "CREATE UNIQUE INDEX UX_Cards_Code ON StudentCards(RegistrationCode)",
    "CREATE TABLE SystemSettings (SettingKey TEXT(60) PRIMARY KEY, SettingValue MEMO, UpdatedAt DATETIME)",
    "CREATE TABLE Counters (CounterKey TEXT(30) PRIMARY KEY, CounterValue LONG NOT NULL)",
    "ALTER TABLE Parents ADD CONSTRAINT FK_Parents_Students FOREIGN KEY (StudentId) REFERENCES Students(StudentId)",
    "ALTER TABLE Guardians ADD CONSTRAINT FK_Guardians_Students FOREIGN KEY (StudentId) REFERENCES Students(StudentId)",
    "ALTER TABLE SemesterResults ADD CONSTRAINT FK_Results_Students FOREIGN KEY (StudentId) REFERENCES Students(StudentId)",
    "ALTER TABLE Applications ADD CONSTRAINT FK_Apps_Students FOREIGN KEY (StudentId) REFERENCES Students(StudentId)",
    "ALTER TABLE ApplicationHistory ADD CONSTRAINT FK_History_Apps FOREIGN KEY (ApplicationId) REFERENCES Applications(ApplicationId)",
    "ALTER TABLE Documents ADD CONSTRAINT FK_Docs_Apps FOREIGN KEY (ApplicationId) REFERENCES Applications(ApplicationId)",
    "ALTER TABLE Payments ADD CONSTRAINT FK_Payments_Apps FOREIGN KEY (ApplicationId) REFERENCES Applications(ApplicationId)",
    "ALTER TABLE Refunds ADD CONSTRAINT FK_Refunds_Apps FOREIGN KEY (ApplicationId) REFERENCES Applications(ApplicationId)",
    "ALTER TABLE StudentCards ADD CONSTRAINT FK_Cards_Students FOREIGN KEY (StudentId) REFERENCES Students(StudentId)"};
   foreach(var s in sql)Exec(c,s);
  }}
  static void Seed(){using(var c=DbConnection.Open()){
   string salt=PasswordHelper.NewSalt(), hash=PasswordHelper.Hash("Admin@123",salt); using(var x=DbConnection.Command("INSERT INTO Users (Username,PasswordHash,PasswordSalt,Role,IsActive,CreatedAt) VALUES (?,?,?,?,?,?)",c,"admin",hash,salt,"Admin",true,DateTime.Now))x.ExecuteNonQuery();
   string[,] settings={{"UniversityName","University of Computer Studies, Pyay"},{"AcademicYear","2026-2027"},{"RegistrationFee","30000"},{"RollNumberPrefix","PaKaPaTa-"},{"UniversityLogoPath",""},{"UniversityPhotoPath",""},{"PaymentQRPath",""},{"PaymentAccountInfo","Demo Payment Account - replace in Settings"},{"RefundPolicy","Admin review required; refunds are not automatic."},{"KPayAccountName","UCS Pyay Finance (Demo)"},{"KPayPhone","09-000000000"},{"WaveAccountName","UCS Pyay Finance (Demo)"},{"WavePhone","09-000000000"},{"BankName","Demo Bank"},{"BankAccountName","UCS Pyay Finance (Demo)"},{"BankAccountNumber","000-000-000"},{"BankBranch","Pyay Demo Branch"}};
   foreach(var s in settings)using(var x=DbConnection.Command("INSERT INTO SystemSettings (SettingKey,SettingValue,UpdatedAt) VALUES (?,?,?)",c,s[0],s[1],DateTime.Now))x.ExecuteNonQuery();
   using(var x=DbConnection.Command("INSERT INTO Counters (CounterKey,CounterValue) VALUES (?,?)",c,"Application2026",0))x.ExecuteNonQuery(); using(var x=DbConnection.Command("INSERT INTO Counters (CounterKey,CounterValue) VALUES (?,?)",c,"RollNumber",2198))x.ExecuteNonQuery();
   using(var x=DbConnection.Command("INSERT INTO AdmissionList (SeatNumber,StudentName,University,AcademicYear,IsEligible) VALUES (?,?,?,?,?)",c,"PYAY-2026-001","Aung Aung","University of Computer Studies, Pyay","2026-2027",true))x.ExecuteNonQuery();
   using(var x=DbConnection.Command("INSERT INTO AdmissionList (SeatNumber,StudentName,University,AcademicYear,IsEligible) VALUES (?,?,?,?,?)",c,"OTHER-2026-009","Mya Mya","Demo Other University","2026-2027",true))x.ExecuteNonQuery();
   using(var x=DbConnection.Command("INSERT INTO Students (StudentName,EnglishName,Gender,DateOfBirth,NRC,Phone,Email,UniversityRollNo,Major,[Year],AcademicYear,CreatedAt) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",c,"Maung Maung","Maung Maung","Male",new DateTime(2005,1,10),"7/PaMaNa(N)111111","09123456789","maung@example.com","PaKaPaTa-002198","Computer Science",2,"2026-2027",DateTime.Now))x.ExecuteNonQuery();
   int sid;using(var x=new OleDbCommand("SELECT @@IDENTITY",c))sid=Convert.ToInt32(x.ExecuteScalar()); using(var x=DbConnection.Command("INSERT INTO SemesterResults (StudentId,AcademicYear,Semester,ResultText,IsPassed,ResultDate) VALUES (?,?,?,?,?,?)",c,sid,"2025-2026",2,"Passed",true,new DateTime(2026,6,1)))x.ExecuteNonQuery();
  }}
 }
}
